uv run --directory backend python -c "import requests, json; base='http://127.0.0.1:8000';
for path,payload in [('/debug', {'message':'spend 40 on groceries today'}), ('/transactions', None)]:
    if payload is None:
        r=requests.get(base+path, timeout=30)
    else:
        r=requests.post(base+path, json=payload, timeout=30)
    print('PATH', path, 'STATUS', r.status_code)
    print(r.text[:4000])
    print('---')
"
